//! 🪆️ Authored identity leaves lend their actual text and exact inverse constructor to the retained semantic owner.
use super::*;
use protocol::{Mutation,MutationMessage,MutationMessageLedgerRetirement,RetainedMutationLeafPreparation,RetainedMutationCloseContext,RetainedMutationAdvance,RetainedMutationDecision,RetainedDiagnosticPreparation,RetainedDiagnosticSpec};
use semio_framework_value::factory::vector::FactoryVectorRetirement;

/// 🏷️ Each authored schema field supplies its native address and typed inverse, without an erased payload map.
pub trait IdentityPayload<M>:Send+Sync+'static{
 const FIELD:IdentityField;
 const INVALID:RetainedDiagnosticSpec;
 const UNCHANGED:RetainedDiagnosticSpec;
 fn source(payload:RetainedCloneRef<'_,Self>)->RetainedCloneRef<'_,String> where Self:Sized;
 fn inverse(value:String)->M;
}

/// 🧳️ Diagnostics and inverse rows keep the exact original factory through every denied or cancelled turn.
pub struct IdentityLeafPreparation<L:IdentityPayload<M>,M:Mutation<EnergyModelSnapshot,Diff=EnergyModelDiff>+Send+'static>{
 core:IdentityChangePreparation,invalid:Option<Box<RetainedDiagnosticPreparation<1>>>,unchanged:Option<Box<RetainedDiagnosticPreparation<0>>>,
 messages:ManuallyDrop<Option<Vec<MutationMessage>>>,message_close:Option<MutationMessageLedgerRetirement>,diff:ManuallyDrop<Option<EnergyModelDiff>>,
 inverse:ManuallyDrop<Option<Vec<M>>>,inverse_close:Option<FactoryVectorRetirement<M>>,diff_source:Option<RetainedCloneBinding>,retirement:RetainedCloneClose,
 phase:u8,inverse_phase:u8,closing:bool,marker:std::marker::PhantomData<fn()->L>,
}
impl<L:IdentityPayload<M>,M:Mutation<EnergyModelSnapshot,Diff=EnergyModelDiff>+Send+'static> IdentityLeafPreparation<L,M>{
 fn check(&self,payload:RetainedCloneRef<'_,L>,original:RetainedCloneRef<'_,EnergyModelSnapshot>)->Result<(),ValueError>{self.core.verify(L::source(payload),original)}
 fn diagnostic_demand(&self,payload:RetainedCloneRef<'_,L>,body:usize)->Result<RetirementDemand,ValueError>{match self.core.outcome().ok_or_else(invalid)?{IdentityOutcome::Refused=>self.invalid.as_ref().ok_or_else(invalid)?.demand([L::source(payload)],body),IdentityOutcome::Unchanged=>self.unchanged.as_ref().ok_or_else(invalid)?.demand([],body),IdentityOutcome::Changed=>Err(invalid())}}
 fn ready(&self,p:RetainedCloneProgress)->RetainedMutationAdvance{if self.phase==6{RetainedMutationAdvance::Ready(p)}else{RetainedMutationAdvance::Progress(p)}}
}
impl<L:IdentityPayload<M>,M:Mutation<EnergyModelSnapshot,Diff=EnergyModelDiff>+Send+'static> RetainedMutationLeafPreparation<EnergyModelSnapshot,M,L> for IdentityLeafPreparation<L,M>{
 fn new()->Self{Self{core:IdentityChangePreparation::new(L::FIELD),invalid:None,unchanged:None,messages:ManuallyDrop::new(None),message_close:None,diff:ManuallyDrop::new(None),inverse:ManuallyDrop::new(None),inverse_close:None,diff_source:None,retirement:Default::default(),phase:0,inverse_phase:0,closing:false,marker:Default::default()}}
 fn decision_demand(&self,payload:RetainedCloneRef<'_,L>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>=6{return Err(invalid());}self.check(payload,original)?;match self.phase{
  0=>nested(self.core.decision_demand(L::source(payload),original,body.saturating_sub(1))?,1),
  1=>{let bytes=match self.core.outcome().ok_or_else(invalid)?{IdentityOutcome::Refused=>size_of::<RetainedDiagnosticPreparation<1>>(),IdentityOutcome::Unchanged=>size_of::<RetainedDiagnosticPreparation<0>>(),_=>return Err(invalid())};Ok(RetirementDemand{copy_bytes:2*bytes+2*size_of::<Option<Box<RetainedDiagnosticPreparation<1>>>>()+1,capacity_bytes:bytes,depth:1,..Default::default()})},
  2=>nested(RetainedDiagnosticPreparation::<0>::start_demand(),1),
  3=>nested(self.diagnostic_demand(payload,body.saturating_sub(1))?,1),
  4=>nested(scalar(size_of::<Vec<MutationMessage>>()),2*size_of::<Option<Vec<MutationMessage>>>()+1),
  5=>if self.core.outcome()==Some(IdentityOutcome::Changed){nested(self.core.take_decision_demand()?,2*size_of::<Option<EnergyModelDiff>>()+2*size_of::<Option<Vec<MutationMessage>>>()+1)}else{Ok(scalar(2*size_of::<Option<EnergyModelDiff>>()+size_of::<EnergyModelDiff>()+1))},
  _=>Err(invalid()),
 }}
 fn decide(&mut self,payload:RetainedCloneRef<'_,L>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.decision_demand(payload,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedMutationAdvance::Progress(Default::default()));}let mut p=receipt(d);match self.phase{
  0=>{p=add(self.core.decide(L::source(payload),original,body.saturating_sub(1),child(g,1)).map_err(|e|tag(e,1))?.progress(),1)?;if self.core.decision_ready(){self.phase=if self.core.outcome()==Some(IdentityOutcome::Changed){5}else{1};}},
  1=>{match self.core.outcome().ok_or_else(invalid)?{IdentityOutcome::Refused=>self.invalid=Some(Box::new(Default::default())),IdentityOutcome::Unchanged=>self.unchanged=Some(Box::new(Default::default())),_=>return Err(invalid())}self.phase=2;},
  2=>{p=add(if let Some(prep)=self.invalid.as_mut(){prep.start(L::INVALID,child(g,1))}else{self.unchanged.as_mut().ok_or_else(invalid)?.start(L::UNCHANGED,child(g,1))}.map_err(|e|tag(e,1))?,1)?;self.phase=3;},
  3=>{let step=if let Some(prep)=self.invalid.as_mut(){prep.advance([L::source(payload)],body.saturating_sub(1),child(g,1))}else{self.unchanged.as_mut().ok_or_else(invalid)?.advance([],body.saturating_sub(1),child(g,1))}.map_err(|e|tag(e,1))?;p=add(step.progress(),1)?;if matches!(step,RetainedCloneStep::Complete(_)){self.phase=4;}},
  4=>{let extra=2*size_of::<Option<Vec<MutationMessage>>>()+1;let(messages,progress)=if let Some(prep)=self.invalid.as_mut(){prep.take(child(g,extra))}else{self.unchanged.as_mut().ok_or_else(invalid)?.take(child(g,extra))}.map_err(|e|tag(e,extra))?.ok_or_else(invalid)?;*self.messages=Some(messages);p=add(progress,extra)?;self.phase=5;},
  5=>{if self.core.outcome()==Some(IdentityOutcome::Changed){let extra=2*size_of::<Option<EnergyModelDiff>>()+2*size_of::<Option<Vec<MutationMessage>>>()+1;let(diff,progress)=self.core.take_decision(child(g,extra)).map_err(|e|tag(e,extra))?.ok_or_else(invalid)?;*self.diff=Some(diff);*self.messages=Some(Vec::new());p=add(progress,extra)?;}else if self.core.outcome()==Some(IdentityOutcome::Unchanged){*self.diff=Some(Default::default());}self.phase=6;},
  _=>return Err(invalid()),
 }semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy identity leaf decision")?;Ok(self.ready(p))}
 fn take_decision(&mut self)->RetainedMutationDecision<EnergyModelDiff>{assert!(self.phase==6&&!self.closing);self.phase=7;let messages=self.messages.take().expect("original semantic diagnostics");if self.core.outcome()==Some(IdentityOutcome::Refused){RetainedMutationDecision::Refused(messages)}else{RetainedMutationDecision::Admitted(self.diff.take().expect("original native identity diff"),messages)}}
 fn inverse_demand(&self,payload:RetainedCloneRef<'_,L>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,diff:RetainedCloneRef<'_,EnergyModelDiff>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase!=7||self.inverse_phase>=4{return Err(invalid());}self.check(payload,original)?;diff.check_binding(&self.diff_source)?;if self.diff_source.is_none(){return Ok(scalar(diff.binding_copy_bytes()));}match self.inverse_phase{
  0=>if self.core.outcome()==Some(IdentityOutcome::Changed){nested(self.core.inverse_demand(original,body.saturating_sub(1))?,1)}else{Ok(scalar(size_of::<Option<Vec<M>>>()+1))},
  1=>Ok(RetirementDemand{copy_bytes:2*size_of::<Option<Vec<M>>>()+1,capacity_bytes:size_of::<M>(),depth:1,..Default::default()}),
  2=>nested(self.core.take_inverse_demand()?,2*size_of::<M>()+size_of::<String>()+2*size_of::<Vec<M>>()+1),
  _=>Err(invalid()),
 }}
 fn inverse(&mut self,payload:RetainedCloneRef<'_,L>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,diff:RetainedCloneRef<'_,EnergyModelDiff>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.inverse_demand(payload,original,diff,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedMutationAdvance::Progress(Default::default()));}if let Some(p)=diff.bind(&mut self.diff_source,g)?{return Ok(RetainedMutationAdvance::Progress(p));}let mut p=receipt(d);match self.inverse_phase{
  0=>if self.core.outcome()==Some(IdentityOutcome::Changed){p=add(self.core.inverse(original,body.saturating_sub(1),child(g,1)).map_err(|e|tag(e,1))?.progress(),1)?;if self.core.inverse_ready(){self.inverse_phase=1;}}else{*self.inverse=Some(Vec::new());self.inverse_phase=4;},
  1=>{*self.inverse=Some(Vec::with_capacity(1));p.retained_capacity_bytes=self.inverse.as_ref().ok_or_else(invalid)?.capacity()*size_of::<M>();self.inverse_phase=2;},
  2=>{let extra=2*size_of::<M>()+size_of::<String>()+2*size_of::<Vec<M>>()+1;let(value,progress)=self.core.take_inverse(child(g,extra)).map_err(|e|tag(e,extra))?.ok_or_else(invalid)?;self.inverse.as_mut().ok_or_else(invalid)?.push(L::inverse(value));self.inverse_phase=4;p=add(progress,extra)?;},
  _=>return Err(invalid()),
 }semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy identity inverse rows")?;Ok(if self.inverse_phase==4{RetainedMutationAdvance::Ready(p)}else{RetainedMutationAdvance::Progress(p)})}
 fn take_inverse(&mut self)->Vec<M>{assert!(self.inverse_phase==4&&!self.closing);self.inverse_phase=5;self.inverse.take().expect("original native inverse rows")}
 fn begin_close(&mut self){self.closing=true;self.core.begin_close();if let Some(p)=self.invalid.as_mut(){p.begin_close();}if let Some(p)=self.unchanged.as_mut(){p.begin_close();}}
 fn close_demand(&self,context:RetainedMutationCloseContext<'_,M>,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if let Some(prep)=self.invalid.as_ref(){return if prep.terminal_is_empty(){Ok(diag_release::<1>())}else{prep.close_demand(body)};}if let Some(prep)=self.unchanged.as_ref(){return if prep.terminal_is_empty(){Ok(diag_release::<0>())}else{prep.close_demand(body)};}if let Some(close)=self.message_close.as_ref(){return Ok(RetirementDemand{copy_bytes:close.next_copy_byte_demand(),capacity_bytes:close.next_capacity_byte_demand(body)?,release_bytes:close.next_release_byte_demand()?,depth:close.next_depth_demand()?});}if self.messages.is_some(){return Ok(scalar(size_of::<MutationMessageLedgerRetirement>()+2*size_of::<Option<Vec<MutationMessage>>>()));}if let Some(close)=self.inverse_close.as_ref(){return close.demands(context.mutations,body);}if self.inverse.is_some(){return Ok(FactoryVectorRetirement::<M>::constructor_demand());}if !self.retirement.is_empty()||self.diff.is_some(){return self.retirement.next_owner_demands::<EnergyModelDiff>(self.diff.is_some(),&None,body);}if !self.core.terminal_is_empty(){return self.core.close_demand(body);}RetainedCloneBinding::close_demand(&self.diff_source,body)}
 fn close_step(&mut self,context:RetainedMutationCloseContext<'_,M>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(context,g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}if let Some(prep)=self.invalid.as_mut(){if prep.terminal_is_empty(){drop(self.invalid.take());return Ok(RetainedCloneStep::Progress(receipt(d)));}return prep.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(prep)=self.unchanged.as_mut(){if prep.terminal_is_empty(){drop(self.unchanged.take());return Ok(RetainedCloneStep::Progress(receipt(d)));}return prep.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(close)=self.message_close.as_mut(){let s=close.close_step(g)?;if close.terminal_is_empty(){self.message_close=None;}return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(messages)=self.messages.take(){self.message_close=Some(MutationMessageLedgerRetirement::new(String::new(),messages));return Ok(RetainedCloneStep::Progress(receipt(d)));}if let Some(close)=self.inverse_close.as_mut(){let s=close.close_step(context.mutations,g)?;if close.terminal_is_empty(){self.inverse_close=None;}return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(rows)=self.inverse.take(){return match FactoryVectorRetirement::admit(rows,g){Ok((close,p))=>{self.inverse_close=Some(close);Ok(RetainedCloneStep::Progress(p))},Err((e,rows))=>{*self.inverse=Some(rows);Err(e)}};}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.diff,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if !self.core.terminal_is_empty(){return self.core.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}let s=RetainedCloneBinding::close_one(&mut self.diff_source,g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.core.terminal_is_empty()&&self.invalid.is_none()&&self.unchanged.is_none()&&self.messages.is_none()&&self.message_close.is_none()&&self.diff.is_none()&&self.inverse.is_none()&&self.inverse_close.is_none()&&self.diff_source.is_none()&&self.retirement.is_empty()}
}
fn diag_release<const N:usize>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Option<Box<RetainedDiagnosticPreparation<N>>>>(),release_bytes:size_of::<RetainedDiagnosticPreparation<N>>(),depth:1,..Default::default()}}
impl<L:IdentityPayload<M>,M:Mutation<EnergyModelSnapshot,Diff=EnergyModelDiff>+Send+'static> Drop for IdentityLeafPreparation<L,M>{fn drop(&mut self){let empty=<Self as RetainedMutationLeafPreparation<EnergyModelSnapshot,M,L>>::terminal_is_empty(self);assert!(std::thread::panicking()||empty,"original identity leaf retains diagnostic or inverse custody");if empty{unsafe{ManuallyDrop::drop(&mut self.messages);ManuallyDrop::drop(&mut self.diff);ManuallyDrop::drop(&mut self.inverse);}}}}
